const changed = (prev, next) => prev.length !== next.length || next.some((d, i) => !Object.is(d, prev[i]));

export function createEffectSlot() {
  let prevDeps;
  let mounted = false;
  let cleanup;
  const runCleanup = () => {
    const c = cleanup;
    cleanup = undefined;
    if (typeof c === 'function') c();
  };
  return {
    render(effect, deps) {
      const run = !mounted || deps === undefined || prevDeps === undefined || changed(prevDeps, deps);
      mounted = true;
      if (!run) return false;
      runCleanup();
      prevDeps = deps;
      cleanup = effect();
      return true;
    },
    unmount() {
      runCleanup();
    },
  };
}

fund-js/20-react-effects-and-rendering/0.explanation:
Decide whether to run, then clean up the previous run, then run and store the new cleanup:

```js
render(effect, deps) {
  const run = !mounted || deps === undefined || prevDeps === undefined || changed(prevDeps, deps);
  mounted = true;
  if (!run) return false;
  runCleanup();
  prevDeps = deps;
  cleanup = effect();
  return true;
}
```

`changed` compares lengths and then every element with `Object.is`, which is why `NaN` is stable while a fresh `{}` always re-runs: exactly the behaviour behind the "object in deps" infinite loop.

Two slips the tests catch. Running the new effect first and the old cleanup afterwards, instead of the other way round, makes "the previous cleanup runs before the next effect" fail, since the log order flips. Calling the stored cleanup without setting `cleanup = undefined` first makes "unmount calls the cleanup exactly once (boundary)" fail on the second `unmount()`.

