  return {
    render(effect, deps) {
      const run = !mounted || deps === undefined || prevDeps === undefined || changed(prevDeps, deps);
      mounted = true;
      if (!run) return false;
      runCleanup();
      prevDeps = deps;
      cleanup = effect();
